INSERT INTO SCHEDULE(
	SCD_ID
	, MBR_CD
	, SCD_TITL_NM
	, SCD_CONT
	, SCD_STR_DTM
	, SCD_END_DTM
	, SCD_RPT_SET_CONT
	, SCD_DEL_YN
	, SCD_LEVEL
)VALUES(
	#{scdId}
	, #{mbrCd}
	, #{scdTitlNm}
	, #{scdCont}
	, #{scdStrDtm}
	, #{scdEndDtm}
	, #{scdRptSetCont}
	, 'N'
	, #{scdLevel}
)

