UPDATE SCHEDULE
SET SCD_TITL_NM = #{scdTitlNm}
	, SCD_CONT = #{scdCont}
	, SCD_STR_DTM = #{scdStrDtm}
	, SCD_END_DTM = #{scdEndDtm}

	, SCD_RPT_SET_CONT = #{scdRptSetCont}


	,SCD_LEVEL = #{scdLevel}

WHERE SCD_ID = #{scdId} 
AND MBR_CD = #{mbrCd}

UPDATE SCHEDULE
SET SCD_DEL_YN = 'Y'
WHERE SCD_ID = #{scdId} 
AND MBR_CD = #{mbrCd}
